#include <cstddef>
#include <iostream>
#include <vector>

std::size_t first_index(const std::vector<int>& values, int target) {
    const std::size_t n = values.size();
    std::size_t i{0};
    while (i < n) {
        if (values[i] == target) {
            return i;
        }
        ++i;
    }
    return n;
}

int main() {
    const std::vector<int> requests{12, 5, 9, 5};
    const std::vector<int> empty{};
    const std::vector<int> one{5};

    std::cout << "duplicate: " << first_index(requests, 5) << '\n';
    std::cout << "absent: " << first_index(requests, 7) << '\n';
    std::cout << "empty: " << first_index(empty, 5) << '\n';
    std::cout << "singleton hit: " << first_index(one, 5) << '\n';
    std::cout << "singleton miss: " << first_index(one, 9) << '\n';
}
